export function walkable(map,x,y){if(map==='mountain'){if(x<300||x>480||y<140||y>460)return false;return !((x>320&&x<365&&y>295&&y<325)||(x>415&&x<465&&y>365&&y<390))}if(map==='classroom')return x>130&&x<665&&y>145&&y<460;if(map==='factory')return x>150&&x<650&&y>150&&y<460;if(map==='corridor')return x>105&&x<695&&y>220&&y<460;return x>100&&x<700&&y>180&&y<460}
export function move(map,p,dx,dy){return {x:walkable(map,p.x+dx,p.y)?p.x+dx:p.x,y:walkable(map,walkable(map,p.x+dx,p.y)?p.x+dx:p.x,p.y+dy)?p.y+dy:p.y}}
